DELETE FROM m_role_permission WHERE permission_id IN
    (SELECT id FROM m_permission WHERE grouping = 'report' AND TRIM(entity_name) IN ('FieldAgentStats','ProgramStats','CoordinatorStats','GroupSummaryCounts','GroupSavingSummary','LoanCyclePerProduct','GroupNamesByStaff','BranchManagerStats','ProgramDetails','ProgramDirectorStats','ChildrenStaffList','FullReportList','ReportCategoryList','ClientSummary','TxnRunningBalances'));
DELETE FROM m_permission WHERE grouping = 'report' AND TRIM(entity_name) IN ('FieldAgentStats','ProgramStats','CoordinatorStats','GroupSummaryCounts','GroupSavingSummary','LoanCyclePerProduct','GroupNamesByStaff','BranchManagerStats','ProgramDetails','ProgramDirectorStats','ChildrenStaffList','FullReportList','ReportCategoryList','ClientSummary','TxnRunningBalances');
DELETE FROM stretchy_report_parameter WHERE report_id IN
    (SELECT id FROM stretchy_report WHERE TRIM(report_name) IN ('FieldAgentStats','ProgramStats','CoordinatorStats','GroupSummaryCounts','GroupSavingSummary','LoanCyclePerProduct','GroupNamesByStaff','BranchManagerStats','ProgramDetails','ProgramDirectorStats','ChildrenStaffList','FullReportList','ReportCategoryList','ClientSummary','TxnRunningBalances'));
DELETE FROM stretchy_report WHERE TRIM(report_name) IN ('FieldAgentStats','ProgramStats','CoordinatorStats','GroupSummaryCounts','GroupSavingSummary','LoanCyclePerProduct','GroupNamesByStaff','BranchManagerStats','ProgramDetails','ProgramDirectorStats','ChildrenStaffList','FullReportList','ReportCategoryList','ClientSummary','TxnRunningBalances');
